INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('多选题', '食品流通', '易', '否', NULL, '除食品的标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的外，生产不符合食品安全标准的食品或者经营明知是不符合食品安全标准的食品，消费者除要求赔偿损失外，还可以：', 'A,B,D', '向生产者或者经营者要求支付价款十倍赔偿金', '向生产者或者经营者要求损失三倍的赔偿金', '向生产者或者经营者要求支付价款二倍的赔偿金', '增加赔偿的金额不足一千元的，为一千元赔偿金；', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('多选题', '食品流通', '易', '是', NULL, '食品生产经营者应当建立食品安全追溯体系，依照食品安全法的规定应如实记录和保存（）信息，保证食品可追溯。', 'A,B,C', '进货查验', '出厂检验', '食品销售', '人员培训', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('多选题', '食品流通', '易', '是', NULL, '食品安全总监等食品安全管理人员每月应向企业主要负责人汇报关于食品安全管理工作情况，包括（）。', 'A,B,C,D,E,F', '本月食品安全管理情况', '本月发现的食品安全风险隐患及其整改情况', '前期尚未整改到位的食品安全风险隐患整改进展情况以及预计完成时限', '食品安全管理方面存在的突出问题及其原因', '下一步食品安全管理工作意见建议', '其他需要汇报的食品安全相关情况', NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('多选题', '食品流通', '易', '是', NULL, '预包装食品的标签内容必须(   )。', 'A,B,C,D', '清晰、醒目、持久；应使消费者购买时易于辨认和识读。', '通俗易懂、准确、有科学依据；不得标示封建迷信、黄色、贬低其他食品或违背科学营养常识的内容。', '不得以虚假、使消费者误解或欺骗性的文字、图形等方式介绍食品；也不得利用字号大小或色差误导消费者。', '不得以直接或间接暗示性的语言、图形、符号，导致消费者将购买的食品或食品的某一性质与另一产品混淆。', NULL, NULL, NULL, NULL, NULL, NULL);
